(function () {
  'use strict';

  /* ---- Dark mode toggle ---- */
  var themeIcon       = document.getElementById('themeIcon');
  var themeIconFooter = document.getElementById('themeIconFooter');
  var btnTheme        = document.getElementById('btnTheme');
  var btnThemeFooter  = document.getElementById('btnThemeFooter');

  function applyThemeIcon(theme) {
    var cls = theme === 'dark' ? 'bi bi-sun-fill' : 'bi bi-moon-stars-fill';
    if (themeIcon)       themeIcon.className = cls;
    if (themeIconFooter) themeIconFooter.className = cls;
  }

  function setTheme(theme) {
    document.documentElement.setAttribute('data-bs-theme', theme);
    localStorage.setItem('biolink-theme', theme);
    applyThemeIcon(theme);
  }

  /* Sincroniza ícone com tema já aplicado pelo FOUC script no <head> */
  applyThemeIcon(document.documentElement.getAttribute('data-bs-theme') || 'light');

  function toggleTheme() {
    setTheme(document.documentElement.getAttribute('data-bs-theme') === 'dark' ? 'light' : 'dark');
  }
  if (btnTheme)       btnTheme.addEventListener('click', toggleTheme);
  if (btnThemeFooter) btnThemeFooter.addEventListener('click', toggleTheme);

  /* ---- Social icon auto-detection ---- */
  function detectIcon(url) {
    var u = url.toLowerCase();
    if      (u.includes('instagram.com'))                            return 'bi bi-instagram';
    else if (u.includes('twitter.com') || u.includes('x.com'))      return 'bi bi-twitter-x';
    else if (u.includes('facebook.com'))                             return 'bi bi-facebook';
    else if (u.includes('youtube.com') || u.includes('youtu.be'))   return 'bi bi-youtube';
    else if (u.includes('tiktok.com'))                               return 'bi bi-tiktok';
    else if (u.includes('whatsapp.com') || u.includes('wa.me'))     return 'bi bi-whatsapp';
    else if (u.includes('linkedin.com'))                             return 'bi bi-linkedin';
    else if (u.includes('github.com'))                               return 'bi bi-github';
    else if (u.includes('spotify.com'))                              return 'bi bi-spotify';
    else if (u.includes('twitch.tv'))                                return 'bi bi-twitch';
    else if (u.includes('threads.net'))                              return 'bi bi-threads';
    else if (u.includes('t.me') || u.includes('telegram.org'))      return 'bi bi-telegram';
    else if (u.includes('snapchat.com'))                             return 'bi bi-snapchat';
    else if (u.includes('pinterest.com'))                            return 'bi bi-pinterest';
    else if (u.includes('mailto:'))                                  return 'bi bi-envelope-at-fill';
    return 'bi bi-link-45deg';
  }

  function applyIcons() {
    document.querySelectorAll('.link-btn').forEach(function (btn) {
      var icon = btn.querySelector('.link-icon');
      if (icon) icon.className = detectIcon(btn.href) + ' link-icon';
    });
    document.querySelectorAll('.social-icon-btn').forEach(function (btn) {
      var icon = btn.querySelector('i');
      if (icon) icon.className = detectIcon(btn.href);
    });
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', applyIcons);
  } else {
    applyIcons();
  }

  /* ---- Web Share API (com fallback clipboard) ---- */
  var isSharing = false;

  function handleShare(btn) {
    if (!btn) return;
    btn.addEventListener('click', function () {
      if (isSharing) return;
      if (navigator.share) {
        navigator.share({
          title: document.title,
          text:  'Confere os meus links!',
          url:   window.location.href
        }).catch(function () { /* usuário cancelou */ });
      } else {
        isSharing = true;
        if (navigator.clipboard) {
          navigator.clipboard.writeText(window.location.href);
        }
        var orig = btn.innerHTML;
        btn.innerHTML = '<i class="bi bi-check2-circle"></i> <span>Copiado!</span>';
        setTimeout(function () { btn.innerHTML = orig; isSharing = false; }, 2500);
      }
    });
  }

  handleShare(document.getElementById('btnShare'));
  handleShare(document.getElementById('btnShareNav'));

  /* ---- Scroll to top ---- */
  var btnTop = document.getElementById('btnScrollToTop');
  if (btnTop) {
    window.addEventListener('scroll', function () {
      btnTop.classList.toggle('visible', window.scrollY > 300);
    }, { passive: true });
    btnTop.addEventListener('click', function () {
      window.scrollTo({ top: 0, behavior: 'smooth' });
    });
  }

})();
